<script>
(function(){
const csrf=<?php echo json_encode($csrf); ?>,manage=<?php echo $manage?'true':'false'; ?>,selectedId=<?php echo (int)($selected['id']??0); ?>,selectedStatus=<?php echo json_encode($selected['status']??''); ?>,selectedType=<?php echo json_encode($selected['period_type']??''); ?>,activeYearId=<?php echo (int)($active['id']??0); ?>,years=<?php echo json_encode(array_map(fn($y)=>['id'=>(int)$y['id'],'year'=>$y['year'],'start'=>$y['start_date'],'end'=>$y['end_date'],'type'=>$y['period_type'],'status'=>$y['status']],$years),JSON_UNESCAPED_UNICODE); ?>,gradeControlApi='academic_year_grade_control_api.php',adminClosureApi='admin_grade_closure_api.php';
