$('#ay-refresh-grade-control').on('click',loadGradeControl);$(document).on('click','.ay-manage-bim',function(){adminBimester=Number($(this).data('bim'));loadClosureMeta().always(buildAdminPanel);$('html,body').animate({scrollTop:$('#ay-admin-close-panel').offset().top-90},200);});$(document).on('change','#ayf-bim',function(){adminBimester=Number($(this).val());loadClosureMeta().always(buildAdminPanel);});$(document).on('change','#ayf-level,#ayf-teacher,#ayf-course,#ayf-grade,#ayf-section,#ayf-state',renderAdminRows);$(document).on('click','#ay-clear-filters',function(){$('#ayf-level,#ayf-teacher,#ayf-course,#ayf-grade,#ayf-section,#ayf-state').val('');renderAdminRows();});$(document).on('change','#ay-select-visible',function(){let checked=this.checked;$('#ay-admin-tbody .ay-row-check:not(:disabled)').prop('checked',checked);$('#ay-admin-mobile-list .ay-row-check:not(:disabled)').prop('checked',checked);});function findItem(id){return currentPeriodItems().find(x=>Number(x.teacher_course_id)===Number(id));}
function showIssues(x){let issues=x&&x.issues?x.issues:[];let html='<div class="mb-2"><strong>'+esc(x.course_name)+' · '+esc(x.grado)+'° '+esc(x.seccion)+'</strong><div class="text-muted small">'+esc(x.teacher_name)+' · '+Number(x.grade_progress||0).toFixed(1)+'% completo</div></div>';if(!issues.length)html+='<div class="alert alert-success mb-0">No hay pendientes detectados.</div>';else{html+='<div class="alert alert-warning"><strong>Pendientes detectados</strong></div><ul class="list-group">';issues.forEach(i=>html+='<li class="list-group-item small">'+esc(i)+'</li>');html+='</ul>';}$('#info-title').text('Detalle de la asignación');$('#info-body').html(html);$('#info-modal').modal('show');}$(document).on('click','.ay-view-issues',function(){let x=findItem($(this).data('id'));if(x)showIssues(x);});$(document).on('click','.ay-view-closure',function(){let x=findItem($(this).data('id')),m=closureMeta[String($(this).data('id'))]||{};if(!x)return;let html='<div class="mb-3"><strong>'+esc(x.course_name)+' · '+esc(x.grado)+'° '+esc(x.seccion)+'</strong><div class="small text-muted">'+esc(x.teacher_name)+' · '+adminBimester+'° Bimestre</div></div><table class="table table-sm"><tr><th>Tipo de cierre</th><td>'+esc(m.mode||'Cerrado')+'</td></tr><tr><th>Realizado por</th><td>'+esc(m.closed_by_name||x.closed_by_name||'—')+'</td></tr><tr><th>Fecha</th><td>'+fmtDate(m.closed_at||x.closed_at)+'</td></tr><tr><th>Versión</th><td>#'+Number(m.closure_version||1)+'</td></tr><tr><th>Motivo</th><td>'+esc(m.reason||'Sin observación adicional')+'</td></tr></table>';$('#info-title').text('Información del cierre');$('#info-body').html(html);$('#info-modal').modal('show');});
function openAdminClose(x,force){if(!x)return;$('#admin-close-tc').val(x.teacher_course_id);$('#admin-close-force').val(force?1:0);$('#admin-close-reason').val('');$('#admin-close-confirm-check').prop('checked',false);$('#admin-close-confirm-wrap').toggle(!!force);$('#admin-close-title').text(force?'Cierre administrativo excepcional':'Cierre administrativo');$('#admin-close-summary').attr('class','alert '+(force?'alert-warning':'alert-info')).html('<strong>'+esc(x.course_name)+' · '+esc(x.grado)+'° '+esc(x.seccion)+'</strong><br>'+esc(x.teacher_name)+' · '+adminBimester+'° Bimestre · '+Number(x.grade_progress||0).toFixed(1)+'% completo');let issues=x.issues||[];$('#admin-close-issues').html(force&&issues.length?'<div class="small mb-3"><strong>Pendientes:</strong><ul class="mb-0 mt-1">'+issues.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>':'');$('#admin-close-confirm').attr('class','btn '+(force?'btn-danger':'btn-success')).html('<i class="fas fa-lock mr-1"></i>'+(force?'Cerrar excepcionalmente':'Cerrar asignación'));$('#admin-close-modal').modal('show');}$(document).on('click','.ay-close-one',function(){openAdminClose(findItem($(this).data('id')),false);});$(document).on('click','.ay-close-exceptional',function(){openAdminClose(findItem($(this).data('id')),true);});$('#admin-close-confirm').on('click',function(){let tc=Number($('#admin-close-tc').val()),force=Number($('#admin-close-force').val()),reason=$.trim($('#admin-close-reason').val());if(force&&reason.length<5){toast('Indique un motivo de al menos 5 caracteres.','warning');return;}if(force&&!$('#admin-close-confirm-check').is(':checked')){toast('Confirme que autoriza el cierre excepcional.','warning');return;}let btn=$(this).prop('disabled',true);adminPost('close_assignment',{academic_year_id:selectedId,teacher_course_id:tc,bimester:adminBimester,force:force,reason:reason}).done(function(r){if(Number(r.status)===1){$('#admin-close-modal').modal('hide');toast(r.message,'success');loadGradeControl();auditLoaded=false;return;}if(Number(r.status)===2){let x=findItem(tc);if(x){x.issues=(r.validation&&r.validation.issues)||x.issues;openAdminClose(x,true);}toast(r.message,'warning');return;}toast(r.message||'No se pudo realizar el cierre.','danger');}).fail(function(x){toast((x.responseJSON||{}).message||'No se pudo realizar el cierre.','danger');}).always(function(){btn.prop('disabled',false);});});function checkedIds(){return [...new Set($('.ay-row-check:checked').map(function(){return Number(this.value);}).get())];}function bulkClose(ids,label){if(!ids.length){toast('No hay asignaciones para cerrar.','warning');return;}if(!confirm('¿Cerrar '+ids.length+' asignación(es) '+label+'? Las incompletas serán omitidas.'))return;adminPost('close_bulk',{academic_year_id:selectedId,bimester:adminBimester,teacher_course_ids:JSON.stringify(ids)}).done(function(r){if(Number(r.status)===1){toast(r.message,r.skipped_count?'warning':'success');loadGradeControl();auditLoaded=false;}else toast(r.message||'No se pudo completar el cierre masivo.','danger');}).fail(function(x){toast((x.responseJSON||{}).message||'No se pudo completar el cierre masivo.','danger');});}$(document).on('click','#ay-close-selected',function(){bulkClose(checkedIds(),'seleccionadas');});$(document).on('click','#ay-close-all-ready',function(){let ids=currentPeriodItems().filter(x=>matchesFilters(x)&&x.ready&&!x.closed).map(x=>Number(x.teacher_course_id));bulkClose(ids,'que están listas');});
function openInstitutionalModal(b,target){if(!gradeControlData)return;let p=gradeControlData.periods&&gradeControlData.periods[b],s=p&&p.summary?p.summary:{},pending=Math.max(0,Number(s.total||0)-Number(s.closed||0));$('#institutional-bimester').val(b);$('#institutional-target').val(target);$('#institutional-reason').val('');let force=target===1&&(pending>0||Number(s.total||0)===0);$('#institutional-force').val(force?1:0);let needsReason=force||target===0;$('#institutional-reason-group').toggle(needsReason);if(target===1){$('#institutional-lock-title').text('Bloquear '+b+'° Bimestre');$('#institutional-confirm').attr('class','btn '+(force?'btn-danger':'btn-primary')).html('<i class="fas fa-lock mr-1"></i>Confirmar bloqueo');$('#institutional-lock-message').attr('class','alert '+(force?'alert-warning':'alert-info')).html(force?'<strong>Bloqueo anticipado.</strong><br>Hay '+pending+' asignación(es) sin cierre. Debes registrar el motivo.':'Todos los cierres están completos. El bloqueo impedirá nuevas modificaciones.');}else{$('#institutional-lock-title').text('Desbloquear '+b+'° Bimestre');$('#institutional-confirm').attr('class','btn btn-warning').html('<i class="fas fa-unlock mr-1"></i>Confirmar desbloqueo');$('#institutional-lock-message').attr('class','alert alert-warning').html('<strong>Importante:</strong> desbloquear no reabre los cierres individuales ya realizados.');}$('#institutional-lock-modal').modal('show');}$(document).on('click','.ay-institutional-lock',function(){openInstitutionalModal(Number($(this).data('bim')),Number($(this).data('target')));});$('#institutional-confirm').on('click',function(){let b=Number($('#institutional-bimester').val()),target=Number($('#institutional-target').val()),force=Number($('#institutional-force').val()),reason=$.trim($('#institutional-reason').val());if((force||target===0)&&reason.length<5){toast('Indique un motivo de al menos 5 caracteres.','warning');return;}let btn=$(this).prop('disabled',true);gradePost('set_lock',{academic_year_id:selectedId,bimester:b,locked:target,force:force,reason:reason}).done(function(r){if(Number(r.status)===1){$('#institutional-lock-modal').modal('hide');toast(r.message,'success');periodsLoaded=false;loadGradeControl();auditLoaded=false;return;}if(Number(r.status)===2){$('#institutional-force').val(1);$('#institutional-reason-group').show();$('#institutional-lock-message').attr('class','alert alert-warning').html(esc(r.message));toast(r.message,'warning');return;}toast(r.message||'No se pudo cambiar el bloqueo.','danger');}).fail(function(x){toast((x.responseJSON||{}).message||'No se pudo cambiar el bloqueo.','danger');}).always(function(){btn.prop('disabled',false);});});
function loadAudit(){auditLoaded=true;$('#audit-body').html('<div class="text-center text-muted py-4"><i class="fas fa-spinner fa-spin mr-2"></i>Cargando auditoría...</div>');$.getJSON('ajax.php?action=get_academic_year_audit',{academic_year_id:selectedId}).done(function(r){let items=r.audit||[],html='<div class="ay-audit-list list-group">';items.forEach(function(x){html+='<div class="list-group-item ay-audit-item"><div class="d-flex justify-content-between"><strong>'+esc(x.action)+'</strong><span class="small text-muted">'+esc(x.created_at)+'</span></div><div class="small text-muted">'+esc(x.user_name||'Sistema')+'</div>'+(x.details?'<div class="small mt-1 text-secondary text-break">'+esc(x.details)+'</div>':'')+'</div>';});html+='</div>';if(!items.length)html='<div class="alert alert-light border mb-0">No hay movimientos registrados para este año.</div>';$('#audit-body').html(html);});}$('#refresh-audit').on('click',loadAudit);
$('#close-selected-year').on('click',function(){gradeGet('annual_checklist',{academic_year_id:selectedId}).done(function(r){if(!r||Number(r.status)!==1){toast((r&&r.message)||'No se pudo obtener el checklist.','danger');return;}let html='<div class="alert '+(r.can_close?'alert-success':'alert-warning')+'"><strong>'+(r.can_close?'Año listo para cierre institucional.':'El año todavía no está listo para cerrar.')+'</strong><div class="small mt-1">Cierres: '+Number((r.closure_summary||{}).closed||0)+' de '+Number((r.closure_summary||{}).total||0)+'.</div></div><ul class="list-group mb-3">';(r.items||[]).forEach(function(x){let badge=x.blocking?'danger':(x.severity==='warning'?'warning':(x.severity==='info'?'info':'success'));html+='<li class="list-group-item d-flex justify-content-between align-items-center"><span>'+esc(x.label)+'</span><span class="badge badge-'+badge+'">'+Number(x.count||0)+'</span></li>';});html+='</ul><div class="form-group"><label>Observación de cierre</label><textarea id="close-notes" class="form-control" rows="3"></textarea></div><button class="btn btn-danger" id="confirm-close-year" '+(r.can_close?'':'disabled')+'><i class="fas fa-lock mr-1"></i>Cerrar año académico</button>';$('#info-title').text('Checklist de cierre anual');$('#info-body').html(html);$('#info-modal').modal('show');});});$(document).on('click','#confirm-close-year',function(){let notes=$.trim($('#close-notes').val());if(notes.length<5){toast('Indique una observación de al menos 5 caracteres.','warning');return;}let btn=$(this).prop('disabled',true);gradePost('close_year',{academic_year_id:selectedId,notes:notes}).done(function(r){if(r&&Number(r.status)===1){toast(r.message,'success');reloadSoon();}else{toast((r&&r.message)||'No se pudo cerrar el año.','danger');btn.prop('disabled',false);}}).fail(function(x){toast((x.responseJSON||{}).message||'No se pudo cerrar el año.','danger');btn.prop('disabled',false);});});$('a[href="#ay-periodos"]').on('shown.bs.tab',loadPeriods);$('a[href="#ay-cierre-notas"]').on('shown.bs.tab',loadGradeControl);$('a[href="#ay-auditoria"]').on('shown.bs.tab',function(){if(!auditLoaded)loadAudit();});loadSummary();
})();
</script>
